fun signIn(request: Any?, deps: Any?): Any? {
    val __f = FddVerify.frame("bp-auth-login")
    __f.enter("NODE-AUTH-LOGIN-001")
    val email: Any? = get(get(request, "body"), "email")
    val emailCheck: Any? = checkEmail(email, "email")
    val password: Any? = get(get(request, "body"), "password")
    __f.enter("NODE-AUTH-LOGIN-006")
    if (!(bool(get(emailCheck, "valid")) && !isEmpty(password))) {
        __f.enter("NODE-AUTH-LOGIN-009")
        return obj(
            "status", 401.0,
            "body", obj(
                "error", if (bool(get(emailCheck, "valid"))) get(checkRequired(password, "password"), "message") else get(emailCheck, "message"),
            ),
        )
    }
    __f.enter("NODE-AUTH-LOGIN-010")
    val lookUpUser: Any? = FddVerify.dep("userService", "getUsersByEmail", "NODE-AUTH-LOGIN-010", obj("query", omitNulls(obj("email", email))))
    val status1: Any? = get(lookUpUser, "status")
    if (eq(status1, 200.0)) {
        __f.enter("NODE-AUTH-LOGIN-014")
        if (!eq(get(get(lookUpUser, "body"), "passwordHash"), format("hash:{password}", obj("password", password)))) {
            __f.enter("NODE-AUTH-LOGIN-021")
            return obj("status", 401.0, "body", obj("error", "Invalid credentials"))
        }
        val id: Any? = get(get(lookUpUser, "body"), "id")
        __f.enter("NODE-AUTH-LOGIN-018")
        FddVerify.dep("eventBus", "publishUserLoggedIn", "NODE-AUTH-LOGIN-018", obj("userId", id))
        __f.enter("NODE-AUTH-LOGIN-019")
        return obj(
            "status", 200.0,
            "body", obj(
                "accessToken", format("TEST-TOKEN-{id}", obj("id", id)),
                "refreshToken", "REFRESH-TOKEN",
                "expiresIn", 3600.0,
                "tokenType", "Bearer",
            ),
        )
    } else if (eq(status1, 404.0)) {
        __f.enter("NODE-AUTH-LOGIN-022")
        return obj("status", 401.0, "body", obj("error", "Invalid credentials"))
    } else {
        __f.enter("NODE-AUTH-LOGIN-023")
        throw FddError("UPSTREAM_ERROR", "User Service failed")
    }
}

