// Runtime for code generated by Rabbinatix from Logic Blueprints. Do not edit: it is regenerated on export.
// Every helper mirrors the simulator, so generated handlers behave exactly like their blueprints.
// Values are JSON values: MutableMap<String, Any?>, MutableList<Any?>, String, Double, Boolean and null.
@file:Suppress("UNCHECKED_CAST", "unused", "MemberVisibilityCanBePrivate")

package fddcheck

import java.lang.reflect.Modifier
import java.lang.reflect.ParameterizedType
import java.lang.reflect.Type
import java.lang.reflect.WildcardType
import java.math.BigDecimal
import java.math.MathContext
import java.math.RoundingMode
import java.nio.ByteBuffer
import java.nio.charset.CharacterCodingException
import java.nio.charset.CodingErrorAction
import java.security.MessageDigest
import java.util.Base64
import java.util.UUID
import java.util.concurrent.ThreadLocalRandom
import java.util.regex.Pattern
import java.util.regex.PatternSyntaxException
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

/** An error with a code, like the simulator's errors (Throw nodes, DIVIDE_BY_ZERO, INVALID_JSON...). */
class FddError(code: Any?, message: Any?) : RuntimeException(asString(message)) {
    val code: String = asString(code)
}

/** The JSON name of a data class property, when it isn't the property's own name. */
@Target(AnnotationTarget.FIELD)
@Retention(AnnotationRetention.RUNTIME)
annotation class FddKey(val value: String)

/** Converts between your own types (data classes, lists, maps) and the JSON values the handlers take and return. */
object FddJson {
    /** A data class, list, map or plain value as JSON values. */
    fun toValue(value: Any?): Any? {
        when (value) {
            null, is String, is Boolean -> return value
            is Number -> return value.toDouble()
            is Char -> return value.toString()
            is Enum<*> -> return value.name
            is Map<*, *> -> {
                val out = LinkedHashMap<String, Any?>()
                for ((k, v) in value) out[k.toString()] = toValue(v)
                return out
            }
            is Iterable<*> -> return value.mapTo(ArrayList()) { toValue(it) }
            is Array<*> -> return value.mapTo(ArrayList()) { toValue(it) }
        }
        val fields = fieldsOf(value.javaClass)
        if (fields.isEmpty()) return value.toString()
        val out = LinkedHashMap<String, Any?>()
        for (f in fields) {
            f.isAccessible = true
            out[jsonName(f)] = toValue(f.get(value))
        }
        return out
    }

    /** JSON values as a data class (or a list, a map, a plain value) of the given type. */
    fun <T> fromValue(value: Any?, type: Class<T>): T = convert(value, type) as T

    /** JSON text as JSON values; fails with IllegalArgumentException. */
    fun parse(json: String): Any? = JsonReader(json).document()

    /** JSON values as JSON text (JSON.stringify). */
    fun stringify(value: Any?): String = json(value)

    private fun fieldsOf(c: Class<*>) = c.declaredFields.filter { !Modifier.isStatic(it.modifiers) && !it.isSynthetic }

    private fun jsonName(f: java.lang.reflect.Field) = f.getAnnotation(FddKey::class.java)?.value ?: f.name

    private fun convert(v: Any?, type: Type): Any? {
        if (type is WildcardType) return convert(v, type.upperBounds.firstOrNull() ?: Any::class.java)
        if (type is ParameterizedType) {
            val raw = type.rawType as Class<*>
            val args = type.actualTypeArguments
            if (v != null && Collection::class.java.isAssignableFrom(raw)) return asArray(v).mapTo(ArrayList()) { convert(it, args[0]) }
            if (v != null && Map::class.java.isAssignableFrom(raw)) {
                val out = LinkedHashMap<String, Any?>()
                if (v is Map<*, *>) for ((k, x) in v) out[k.toString()] = convert(x, args[1])
                return out
            }
            return convert(v, raw)
        }
        val c = type as? Class<*> ?: return v
        if (c == Any::class.java) return v
        if (v == null) {
            return when (c) {
                java.lang.Boolean.TYPE -> false
                java.lang.Double.TYPE -> 0.0
                java.lang.Long.TYPE -> 0L
                Integer.TYPE -> 0
                else -> null
            }
        }
        when (c) {
            String::class.java -> return v as? String ?: jsString(v)
            java.lang.Double::class.java, java.lang.Double.TYPE -> return toNum(v)
            java.lang.Long::class.java, java.lang.Long.TYPE -> return toNum(v).toLong()
            Integer::class.java, Integer.TYPE -> return toNum(v).toInt()
            java.lang.Boolean::class.java, java.lang.Boolean.TYPE -> return truthy(v)
        }
        if (c.isPrimitive || c.isInterface || c.name.startsWith("java.") || c.name.startsWith("kotlin.")) return v
        val fields = fieldsOf(c)
        val m = v as? Map<*, *> ?: throw IllegalArgumentException("Expected an object for " + c.simpleName)
        val ctor = c.declaredConstructors.firstOrNull { k -> k.parameterCount == fields.size && k.parameterTypes.indices.all { k.parameterTypes[it] == fields[it].type } }
            ?: throw IllegalArgumentException("No constructor for " + c.simpleName)
        ctor.isAccessible = true
        return ctor.newInstance(*fields.map { convert(m[jsonName(it)], it.genericType) }.toTypedArray())
    }
}

/** Strict JSON (what JSON.parse accepts); numbers become doubles. */
private class JsonReader(private val s: String) {
    private var i = 0

    fun document(): Any? {
        ws()
        val v = value()
        ws()
        if (i != s.length) throw bad()
        return v
    }

    private fun bad() = IllegalArgumentException("Not valid JSON at $i")

    private fun ws() {
        while (i < s.length && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\r')) i++
    }

    private fun peek(): Char {
        if (i >= s.length) throw bad()
        return s[i]
    }

    private fun value(): Any? = when (peek()) {
        '{' -> obj()
        '[' -> array()
        '"' -> string()
        't' -> word("true", true)
        'f' -> word("false", false)
        'n' -> word("null", null)
        else -> number()
    }

    private fun word(w: String, v: Any?): Any? {
        if (!s.startsWith(w, i)) throw bad()
        i += w.length
        return v
    }

    private fun obj(): MutableMap<String, Any?> {
        val m = LinkedHashMap<String, Any?>()
        i++
        ws()
        if (peek() == '}') {
            i++
            return m
        }
        while (true) {
            ws()
            if (peek() != '"') throw bad()
            val k = string()
            ws()
            if (peek() != ':') throw bad()
            i++
            ws()
            m[k] = value()
            ws()
            val c = peek()
            i++
            if (c == '}') return m
            if (c != ',') throw bad()
        }
    }

    private fun array(): MutableList<Any?> {
        val l = ArrayList<Any?>()
        i++
        ws()
        if (peek() == ']') {
            i++
            return l
        }
        while (true) {
            ws()
            l.add(value())
            ws()
            val c = peek()
            i++
            if (c == ']') return l
            if (c != ',') throw bad()
        }
    }

    private fun string(): String {
        i++
        val sb = StringBuilder()
        while (true) {
            val c = peek()
            i++
            if (c == '"') return sb.toString()
            if (c < ' ') throw bad()
            if (c != '\\') {
                sb.append(c)
                continue
            }
            val e = peek()
            i++
            when (e) {
                '"', '\\', '/' -> sb.append(e)
                'b' -> sb.append('\b')
                'f' -> sb.append('\u000c')
                'n' -> sb.append('\n')
                'r' -> sb.append('\r')
                't' -> sb.append('\t')
                'u' -> {
                    if (i + 4 > s.length) throw bad()
                    var code = 0
                    repeat(4) {
                        val d = Character.digit(s[i++], 16)
                        if (d < 0) throw bad()
                        code = code * 16 + d
                    }
                    sb.append(code.toChar())
                }
                else -> throw bad()
            }
        }
    }

    private fun number(): Any {
        val start = i
        if (i < s.length && s[i] == '-') i++
        if (i < s.length && s[i] == '0') i++ else if (!digits()) throw bad()
        if (i < s.length && s[i] == '.') {
            i++
            if (!digits()) throw bad()
        }
        if (i < s.length && (s[i] == 'e' || s[i] == 'E')) {
            i++
            if (i < s.length && (s[i] == '+' || s[i] == '-')) i++
            if (!digits()) throw bad()
        }
        return s.substring(start, i).toDouble()
    }

    private fun digits(): Boolean {
        val start = i
        while (i < s.length && s[i] in '0'..'9') i++
        return i > start
    }
}

// ---------- the value model the generated code uses ----------

/** A condition: true only for true, else JavaScript truthiness. */
fun bool(v: Any?): Boolean = if (v is Boolean) v else truthy(v)

/** A number operand. */
fun num(v: Any?): Double = if (v is Number) v.toDouble() else toNum(v)

/** o.name, null-safe: null when o is null or has no such field. */
fun get(o: Any?, name: String): Any? = key(o, name)

/** o[key], null-safe. */
fun item(o: Any?, k: Any?): Any? = key(o, k)

/** An object from key, value, key, value... */
fun obj(vararg fields: Any?): MutableMap<String, Any?> {
    val d = LinkedHashMap<String, Any?>()
    var i = 0
    while (i + 1 < fields.size) {
        d[fields[i] as String] = fields[i + 1]
        i += 2
    }
    return d
}

fun arr(vararg items: Any?): MutableList<Any?> = items.toCollection(ArrayList())

/** a === b for strings, numbers, booleans and null. */
fun eq(a: Any?, b: Any?): Boolean = when (a) {
    null -> b == null
    is Number -> b is Number && a.toDouble() == b.toDouble()
    is String -> b is String && a == b
    is Boolean -> b is Boolean && a == b
    else -> a === b
}

fun iter(v: Any?): List<Any?> = v as? List<Any?> ?: emptyList()

/** (index, item) pairs of a list; the index is a number. */
fun indexed(v: Any?): List<Pair<Double, Any?>> = iter(v).mapIndexed { i, x -> Pair(i.toDouble(), x) }

/** from, from + 1, ... up to and including to (to is read once). */
fun range(from: Double, to: Double): Sequence<Double> = generateSequence(from) { it + 1 }.takeWhile { it <= to }

/** from, from + 1, ... without end (the loop stops itself). */
fun counting(from: Double): Sequence<Double> = generateSequence(from) { it + 1 }

fun map(items: Any?, fn: (Any?, Any?) -> Any?): MutableList<Any?> = asArray(items).mapIndexedTo(ArrayList()) { i, x -> fn(x, i.toDouble()) }

fun filter(items: Any?, fn: (Any?, Any?) -> Boolean): MutableList<Any?> {
    val out = ArrayList<Any?>()
    asArray(items).forEachIndexed { i, x -> if (fn(x, i.toDouble())) out.add(x) }
    return out
}

fun find(items: Any?, fn: (Any?, Any?) -> Boolean): Any? {
    asArray(items).forEachIndexed { i, x -> if (fn(x, i.toDouble())) return x }
    return null
}

fun some(items: Any?, fn: (Any?, Any?) -> Boolean): Boolean {
    asArray(items).forEachIndexed { i, x -> if (fn(x, i.toDouble())) return true }
    return false
}

fun every(items: Any?, fn: (Any?, Any?) -> Boolean): Boolean {
    asArray(items).forEachIndexed { i, x -> if (!fn(x, i.toDouble())) return false }
    return true
}

private fun key(o: Any?, k: Any?): Any? {
    when (o) {
        is Map<*, *> -> return o[k as? String ?: jsString(k)]
        is List<*> -> {
            if (k == "length") return o.size.toDouble()
            val i = index(k)
            return if (i >= 0 && i < o.size) o[i] else null
        }
        is String -> {
            if (k == "length") return o.length.toDouble()
            val i = index(k)
            return if (i >= 0 && i < o.length) o[i].toString() else null
        }
    }
    return null
}

/** A list position, or -1. */
private fun index(k: Any?): Int {
    val d = when (k) {
        is Number -> k.toDouble()
        is String -> if (k.isNotEmpty() && k.all { it in '0'..'9' }) k.toDouble() else return -1
        else -> return -1
    }
    return if (d >= 0 && d < Int.MAX_VALUE && Math.floor(d) == d) d.toInt() else -1
}

private fun trunc(d: Double): Double = if (d < 0) Math.ceil(d) else Math.floor(d)

// ---------- JavaScript conversions ----------

/** A number as JavaScript's String(n) writes it. */
fun numText(n: Double): String {
    if (n.isNaN()) return "NaN"
    if (n.isInfinite()) return if (n > 0) "Infinity" else "-Infinity"
    if (n == 0.0) return "0"
    if (Math.abs(n) < 1e15 && Math.floor(n) == n) return n.toLong().toString()
    // the shortest digits that read back as the same double
    val exact = BigDecimal(Math.abs(n))
    var b = exact
    for (p in 1..17) {
        val c = exact.round(MathContext(p, RoundingMode.HALF_EVEN))
        if (c.toDouble() == Math.abs(n)) {
            b = c
            break
        }
    }
    var digits = b.unscaledValue().toString()
    val point = digits.length - b.scale()
    digits = digits.trimEnd('0').ifEmpty { "0" }
    val k = digits.length
    val sign = if (n < 0) "-" else ""
    if (point in k..21) return sign + digits + "0".repeat(point - k)
    if (point in 1..21) return sign + digits.substring(0, point) + "." + digits.substring(point)
    if (point in -5..0) return sign + "0." + "0".repeat(-point) + digits
    val x = point - 1
    return sign + digits[0] + (if (k > 1) "." + digits.substring(1) else "") + "e" + (if (x >= 0) "+" else "-") + Math.abs(x)
}

/** String(v). */
fun jsString(v: Any?): String = when (v) {
    null -> "null"
    is Boolean -> if (v) "true" else "false"
    is Number -> numText(v.toDouble())
    is String -> v
    is List<*> -> v.joinToString(",") { if (it == null) "" else jsString(it) }
    is Map<*, *> -> "[object Object]"
    is Throwable -> v.message ?: v.javaClass.simpleName
    else -> v.toString()
}

/** JSON.stringify. */
fun json(v: Any?): String {
    val sb = StringBuilder()
    write(sb, v)
    return sb.toString()
}

private fun write(sb: StringBuilder, v: Any?) {
    when (v) {
        null -> sb.append("null")
        is Boolean -> sb.append(if (v) "true" else "false")
        is Number -> {
            val d = v.toDouble()
            sb.append(if (d.isFinite()) numText(d) else "null")
        }
        is String -> quote(sb, v)
        is List<*> -> {
            sb.append('[')
            v.forEachIndexed { i, x ->
                if (i > 0) sb.append(',')
                write(sb, x)
            }
            sb.append(']')
        }
        is Map<*, *> -> {
            sb.append('{')
            keyList(v).forEachIndexed { i, k ->
                if (i > 0) sb.append(',')
                quote(sb, k)
                sb.append(':')
                write(sb, v[k])
            }
            sb.append('}')
        }
        else -> quote(sb, v.toString())
    }
}

private fun quote(sb: StringBuilder, s: String) {
    sb.append('"')
    for ((i, c) in s.withIndex()) {
        when {
            c == '"' -> sb.append("\\\"")
            c == '\\' -> sb.append("\\\\")
            c == '\n' -> sb.append("\\n")
            c == '\r' -> sb.append("\\r")
            c == '\t' -> sb.append("\\t")
            c == '\b' -> sb.append("\\b")
            c == '\u000c' -> sb.append("\\f")
            c < ' ' -> sb.append(String.format("\\u%04x", c.code))
            // a lone surrogate is escaped, as JSON.stringify does
            c.isHighSurrogate() && !(i + 1 < s.length && s[i + 1].isLowSurrogate()) -> sb.append(String.format("\\u%04x", c.code))
            c.isLowSurrogate() && !(i > 0 && s[i - 1].isHighSurrogate()) -> sb.append(String.format("\\u%04x", c.code))
            else -> sb.append(c)
        }
    }
    sb.append('"')
}

/** JavaScript's white space and line terminators (what String.prototype.trim removes). */
private fun jsSpace(c: Char): Boolean =
    c == ' ' || c in '\t'..'\r' || c == '\u00a0' || c == '\u1680' || c in '\u2000'..'\u200a' || c == '\u2028' || c == '\u2029' ||
        c == '\u202f' || c == '\u205f' || c == '\u3000' || c == '\ufeff'

private fun jsTrim(s: String): String = s.trim { jsSpace(it) }

private val DECIMAL = Pattern.compile("^[+-]?(\\d+\\.?\\d*|\\.\\d+)([eE][+-]?\\d+)?$")

/** Number(v). */
fun jsNumber(v: Any?): Double {
    when (v) {
        null -> return 0.0
        is Boolean -> return if (v) 1.0 else 0.0
        is Number -> return v.toDouble()
        is String -> {
            val t = jsTrim(v)
            if (t.isEmpty()) return 0.0
            if (t.length > 2 && t[0] == '0' && t[1] in "xXoObB") {
                val radix = when (t[1]) { 'x', 'X' -> 16; 'o', 'O' -> 8; else -> 2 }
                var acc = 0.0
                for (c in t.substring(2)) {
                    val d = if (c.code < 128) Character.digit(c, radix) else -1
                    if (d < 0) return Double.NaN
                    acc = acc * radix + d
                }
                return acc
            }
            if (t == "Infinity" || t == "+Infinity") return Double.POSITIVE_INFINITY
            if (t == "-Infinity") return Double.NEGATIVE_INFINITY
            return if (DECIMAL.matcher(t).matches()) t.toDouble() else Double.NaN
        }
        is List<*> -> {
            if (v.isEmpty()) return 0.0
            if (v.size == 1) {
                val x = v[0]
                return if (x is List<*> || x is Map<*, *>) Double.NaN else if (x == null) 0.0 else jsNumber(x)
            }
        }
    }
    return Double.NaN
}

private fun prim(x: Any?): Any? = if (x is List<*> || x is Map<*, *>) jsString(x) else x

private fun lt(a: Any?, b: Any?): Boolean = if (a is String && b is String) a < b else jsNumber(prim(a)) < jsNumber(prim(b))

// ---------- values ----------

/** Branch semantics: "" and "false" are false. */
fun truthy(v: Any?): Boolean = when (v) {
    null -> false
    is String -> v.isNotEmpty() && v != "false"
    is Boolean -> v
    is Number -> v.toDouble() != 0.0 && !v.toDouble().isNaN()
    else -> true
}

/** null, "", [] or {}. */
fun isEmpty(v: Any?): Boolean = when (v) {
    null -> true
    is String -> jsTrim(v).isEmpty()
    is List<*> -> v.isEmpty()
    is Map<*, *> -> v.isEmpty()
    else -> false
}

/** null or missing. */
fun isNull(v: Any?): Boolean = v == null

/** Structural equality (objects and arrays by value). */
fun deepEqual(a: Any?, b: Any?): Boolean {
    if (a is Number && b is Number) {
        val x = a.toDouble()
        val y = b.toDouble()
        return x == y || (x.isNaN() && y.isNaN())
    }
    if (a is List<*> && b is List<*>) return a.size == b.size && a.indices.all { deepEqual(a[it], b[it]) }
    if (a is Map<*, *> && b is Map<*, *>) return a.size == b.size && a.keys.all { b.containsKey(it) && deepEqual(a[it], b[it]) }
    return eq(a, b)
}

/** -1, 0 or 1. */
fun compare(a: Any?, b: Any?): Double = if (deepEqual(a, b)) 0.0 else if (lt(a, b)) -1.0 else 1.0

/** An arithmetic operand: numbers as is, anything else through Number(). */
fun toNum(v: Any?): Double = if (v is Number) v.toDouble() else jsNumber(v)

/** Fails on zero. */
fun divide(a: Any?, b: Any?): Double {
    if (toNum(b) == 0.0) throw FddError("DIVIDE_BY_ZERO", "Division by zero")
    return toNum(a) / toNum(b)
}

/** The value if it is an array, else []. */
fun asArray(v: Any?): MutableList<Any?> = v as? MutableList<Any?> ?: (v as? List<Any?>)?.toMutableList() ?: ArrayList()

private fun asMap(v: Any?): Map<String, Any?> = v as? Map<String, Any?> ?: emptyMap()

/** A query found something (not null, not an empty list). */
fun isFound(v: Any?): Boolean = if (v is List<*>) v.isNotEmpty() else v != null

/** Drops null entries (query and header maps). */
fun omitNulls(o: Any?): MutableMap<String, Any?> {
    val out = LinkedHashMap<String, Any?>()
    for ((k, v) in asMap(o)) if (v != null) out[k] = v
    return out
}

// ---------- paths & objects ----------

/** A path that isn't there (JavaScript's undefined): left out of objects, like JSON.stringify does. */
private object Missing

private class Seg(val name: String?, val index: Int) {
    val key: String get() = name ?: index.toString()
    val value: Any get() = name ?: index.toDouble()
}

private val SEGMENT = Pattern.compile("([^\\[\\]]+)|\\[(\\d+)\\]")

/** user.roles[0].name */
private fun segments(path: String): List<Seg> {
    val out = ArrayList<Seg>()
    for (part in path.split(".")) {
        if (part.isEmpty()) continue
        val m = SEGMENT.matcher(part)
        while (m.find()) {
            if (m.group(1) != null) out.add(Seg(m.group(1), -1))
            else out.add(Seg(null, m.group(2).toIntOrNull() ?: Int.MAX_VALUE))
        }
    }
    return out
}

private fun unsafe(segs: List<Seg>) = segs.any { it.name == "__proto__" || it.name == "constructor" || it.name == "prototype" }

/** The path exists (its value may be null). */
fun hasPath(value: Any?, path: Any?): Boolean {
    val p = str(path)
    if (p.isEmpty() || p == "$") return true
    val segs = segments(p)
    if (unsafe(segs)) return false
    var cur = value
    for (s in segs) {
        cur = when (cur) {
            is Map<*, *> -> if (cur.containsKey(s.key)) cur[s.key] else return false
            is List<*> -> if (s.name == "length") cur.size.toDouble() else if (s.name == null && s.index < cur.size) cur[s.index] else return false
            is String -> if (s.name == "length") cur.length.toDouble() else if (s.name == null && s.index < cur.length) cur[s.index].toString() else return false
            else -> return false
        }
    }
    return true
}

/** Reads a nested value; null when a step is missing. */
fun getPath(value: Any?, path: Any?): Any? {
    val p = str(path)
    if (p.isEmpty() || p == "$") return value
    val segs = segments(p)
    if (unsafe(segs)) return null
    var cur = value
    for (s in segs) {
        if (cur == null) return null
        cur = key(cur, s.value)
    }
    return cur
}

private fun lookup(value: Any?, path: String): Any? = if (hasPath(value, path)) getPath(value, path) else Missing

private fun container(v: Any?) = v is List<*> || v is Map<*, *>

private fun shallowCopy(v: Any?): Any? = when (v) {
    is List<*> -> ArrayList(v)
    is Map<*, *> -> LinkedHashMap(v as Map<String, Any?>)
    else -> v
}

private fun emptyFor(next: Seg): Any = if (next.name == null) ArrayList<Any?>() else LinkedHashMap<String, Any?>()

/** A copy with a nested value set. */
fun setPath(value: Any?, path: Any?, v: Any?): Any? {
    val segs = segments(str(path))
    if (segs.isEmpty()) return v
    val root = if (container(value)) shallowCopy(value) else LinkedHashMap<String, Any?>()
    if (unsafe(segs)) return root
    setIn(root, segs, 0, v)
    return root
}

/** Sets segs[i..] in cur, a fresh copy. */
private fun setIn(cur: Any?, segs: List<Seg>, i: Int, v: Any?) {
    val s = segs[i]
    val last = i == segs.size - 1
    if (cur is MutableList<*>) {
        val l = cur as MutableList<Any?>
        if (s.name != null) return
        while (l.size <= s.index) l.add(null)
        if (last) {
            if (v !== Missing) l[s.index] = v
            return
        }
        var next = shallowCopy(l[s.index])
        if (!container(next)) next = emptyFor(segs[i + 1])
        l[s.index] = next
        setIn(next, segs, i + 1, v)
        return
    }
    val d = cur as MutableMap<String, Any?>
    if (last) {
        if (v !== Missing) d[s.key] = v
        return
    }
    var next = if (d.containsKey(s.key)) shallowCopy(d[s.key]) else null
    if (!container(next)) next = emptyFor(segs[i + 1])
    d[s.key] = next
    setIn(next, segs, i + 1, v)
}

private fun deepClone(v: Any?): Any? = when (v) {
    is List<*> -> v.mapTo(ArrayList()) { deepClone(it) }
    is Map<*, *> -> {
        val o = LinkedHashMap<String, Any?>()
        for ((k, x) in v) o[k as String] = deepClone(x)
        o
    }
    else -> v
}

/** A copy without a nested value. */
fun removePath(value: Any?, path: Any?): Any? {
    val segs = segments(str(path))
    if (segs.isEmpty() || !container(value)) return value
    val clone = deepClone(value)
    if (unsafe(segs)) return clone
    removeIn(clone, segs, 0)
    return clone
}

private fun removeIn(cur: Any?, segs: List<Seg>, i: Int) {
    val s = segs[i]
    if (i == segs.size - 1) {
        if (cur is MutableList<*> && s.name == null && s.index < cur.size) cur.removeAt(s.index)
        else if (cur is MutableMap<*, *>) (cur as MutableMap<String, Any?>).remove(s.key)
        return
    }
    val next = when (cur) {
        is Map<*, *> -> cur[s.key]
        is List<*> -> if (s.name == null && s.index < cur.size) cur[s.index] else null
        else -> null
    }
    if (container(next)) removeIn(next, segs, i + 1)
}

private fun spread(v: Any?): Map<String, Any?> = when (v) {
    is Map<*, *> -> v as Map<String, Any?>
    is List<*> -> v.withIndex().associate { (i, x) -> i.toString() to x }
    is String -> v.withIndex().associate { (i, c) -> i.toString() to c.toString() }
    else -> emptyMap()
}

/** Shallow merge, B over A. */
fun merge(a: Any?, b: Any?): MutableMap<String, Any?> {
    val d = LinkedHashMap<String, Any?>()
    d.putAll(spread(a))
    d.putAll(spread(b))
    return d
}

/** A new object: target path from source path. */
fun transform(source: Any?, mapping: Any?): Any? {
    var out: Any? = LinkedHashMap<String, Any?>()
    for (pair in asArray(mapping)) {
        val p = asArray(pair)
        out = setPath(out, p.getOrNull(0), lookup(source, str(p.getOrNull(1))))
    }
    return out
}

private val PLACEHOLDER = Pattern.compile("\\{\\{\\s*([^}]+?)\\s*\\}\\}")
private val WHOLE_PLACEHOLDER = Pattern.compile("^\\{\\{\\s*([^}]+?)\\s*\\}\\}$")

/** Fills {{path}} placeholders from data. */
fun template(value: Any?, data: Any?): Any? {
    val r = fill(value, data)
    return if (r === Missing) null else r
}

private fun fill(value: Any?, data: Any?): Any? {
    when (value) {
        is String -> {
            val whole = WHOLE_PLACEHOLDER.matcher(value)
            if (whole.matches()) return lookup(data, whole.group(1))
            val m = PLACEHOLDER.matcher(value)
            val sb = StringBuffer()
            while (m.find()) {
                val r = getPath(data, m.group(1))
                val text = if (r == null) "" else if (container(r)) json(r) else jsString(r)
                m.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(text))
            }
            m.appendTail(sb)
            return sb.toString()
        }
        is List<*> -> return value.mapTo(ArrayList()) { x -> fill(x, data).let { if (it === Missing) null else it } }
        is Map<*, *> -> {
            val o = LinkedHashMap<String, Any?>()
            for ((k, x) in value) {
                val z = fill(x, data)
                if (z !== Missing) o[k as String] = z
            }
            return o
        }
    }
    return value
}

/** JSON.parse that fails with INVALID_JSON. */
fun parseJson(text: Any?): Any? = try {
    FddJson.parse(jsString(text))
} catch (e: IllegalArgumentException) {
    throw FddError("INVALID_JSON", "Not valid JSON")
}

/** The { code, message } a Catch or Failed pin receives. */
fun toError(e: Throwable): MutableMap<String, Any?> =
    if (e is FddError) obj("code", e.code, "message", e.message) else obj("code", "RUNTIME_ERROR", "message", e.message ?: e.javaClass.simpleName)

// ---------- strings ----------

/** A string operand: null is "". */
fun str(v: Any?): String = if (v == null) "" else jsString(v)

/** String(v), like a Switch compares. */
fun asString(v: Any?): String = jsString(v)

fun contains(text: Any?, search: Any?): Boolean = str(text).contains(str(search))

fun startsWith(text: Any?, prefix: Any?): Boolean = str(text).startsWith(str(prefix))

fun endsWith(text: Any?, suffix: Any?): Boolean = str(text).endsWith(str(suffix))

fun trim(text: Any?): String = jsTrim(str(text))

fun lower(text: Any?): String = str(text).lowercase()

fun upper(text: Any?): String = str(text).uppercase()

fun strLength(text: Any?): Double = str(text).length.toDouble()

fun concat(a: Any?, b: Any?): String = str(a) + str(b)

fun replaceAll(text: Any?, search: Any?, replacement: Any?): String {
    val t = str(text)
    val s = str(search)
    val r = str(replacement)
    if (s.isNotEmpty()) return t.replace(s, r)
    return t.toCharArray().joinToString(r)
}

/** An empty separator splits on ",". */
fun split(text: Any?, separator: Any?): MutableList<Any?> = str(text).split(str(separator).ifEmpty { "," }).toMutableList()

fun join(items: Any?, separator: Any?): String = asArray(items).joinToString(str(separator)) { str(it) }

private fun rx(pattern: String, flags: String): Pattern {
    var o = 0
    for (c in flags) {
        if (c !in "gimsuyd") throw PatternSyntaxException("flags", flags, 0)
        if (c == 'i') o = o or Pattern.CASE_INSENSITIVE or Pattern.UNICODE_CASE
        if (c == 'm') o = o or Pattern.MULTILINE
        if (c == 's') o = o or Pattern.DOTALL
    }
    return Pattern.compile(pattern, o)
}

fun regexMatch(text: Any?, pattern: Any?, flags: Any?): MutableMap<String, Any?> {
    val re = try {
        rx(str(pattern), str(flags))
    } catch (e: PatternSyntaxException) {
        throw FddError("INVALID_REGEX", "Invalid pattern " + str(pattern))
    }
    val m = re.matcher(str(text))
    val found = m.find()
    val groups = ArrayList<Any?>()
    if (found) for (i in 1..m.groupCount()) groups.add(m.group(i))
    return obj("matches", found, "groups", groups)
}

private val NAMED = Pattern.compile("\\{(\\w+)\\}")

/** Fills {name} placeholders. */
fun format(template: Any?, values: Any?): String {
    val m = NAMED.matcher(str(template))
    val sb = StringBuffer()
    while (m.find()) m.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(str(get(values, m.group(1)))))
    m.appendTail(sb)
    return sb.toString()
}

// ---------- collections ----------

fun len(a: Any?): Double = if (a is List<*>) a.size.toDouble() else 0.0

fun at(a: Any?, i: Any?): Any? = key(asArray(a), toNum(i))

/** A copy with the item appended. */
fun append(a: Any?, item: Any?): MutableList<Any?> {
    val out = ArrayList(asArray(a))
    out.add(item)
    return out
}

/** Deep-equal membership. */
fun includes(a: Any?, item: Any?): Boolean = asArray(a).any { deepEqual(it, item) }

fun sum(a: Any?, path: Any?): Double {
    val p = str(path)
    var t = 0.0
    for (x in asArray(a)) t += toNum(if (p.isNotEmpty()) getPath(x, p) else x)
    return t
}

fun sortBy(a: Any?, path: Any?, desc: Any?): MutableList<Any?> {
    val dir = if (truthy(desc)) -1 else 1
    val p = str(path)
    val items = ArrayList(asArray(a))
    // a stable merge sort, like Array.prototype.sort (it never fails on an inconsistent order)
    mergeSort(items) { x, y ->
        val u = if (p.isNotEmpty()) getPath(x, p) else x
        val w = if (p.isNotEmpty()) getPath(y, p) else y
        if (lt(u, w)) -dir else if (lt(w, u)) dir else 0
    }
    return items
}

private fun mergeSort(l: MutableList<Any?>, c: (Any?, Any?) -> Int) {
    if (l.size < 2) return
    val mid = l.size / 2
    val a = ArrayList(l.subList(0, mid))
    val b = ArrayList(l.subList(mid, l.size))
    mergeSort(a, c)
    mergeSort(b, c)
    var i = 0
    var j = 0
    var k = 0
    while (i < a.size && j < b.size) l[k++] = if (c(b[j], a[i]) < 0) b[j++] else a[i++]
    while (i < a.size) l[k++] = a[i++]
    while (j < b.size) l[k++] = b[j++]
}

/** One item at a time (deterministic order). */
fun mapAsync(items: Any?, fn: (Any?, Any?) -> Any?): MutableList<Any?> = map(items, fn)

fun filterAsync(items: Any?, fn: (Any?, Any?) -> Any?): MutableList<Any?> = filter(items) { x, i -> truthy(fn(x, i)) }

fun findAsync(items: Any?, fn: (Any?, Any?) -> Any?): Any? = find(items) { x, i -> truthy(fn(x, i)) }

fun someAsync(items: Any?, fn: (Any?, Any?) -> Any?): Boolean = some(items) { x, i -> truthy(fn(x, i)) }

fun everyAsync(items: Any?, fn: (Any?, Any?) -> Any?): Boolean = every(items) { x, i -> truthy(fn(x, i)) }

/** The first item, or null. */
fun first(a: Any?): Any? = asArray(a).firstOrNull()

/** The last item, or null. */
fun last(a: Any?): Any? = asArray(a).lastOrNull()

/** Groups items by the text of a path: { value: [items] }. */
fun groupBy(a: Any?, path: Any?): MutableMap<String, Any?> {
    val p = str(path)
    val groups = LinkedHashMap<String, Any?>()
    for (x in asArray(a)) {
        val k = toStringValue(if (p.isNotEmpty()) getPath(x, p) else x)
        (groups.getOrPut(k) { ArrayList<Any?>() } as MutableList<Any?>).add(x)
    }
    val out = LinkedHashMap<String, Any?>()
    for (k in keyList(groups)) out[k] = groups[k]
    return out
}

/** The mean of numbers or of a path; 0 for an empty list. */
fun average(a: Any?, path: Any?): Double {
    val n = asArray(a).size
    return if (n == 0) 0.0 else sum(a, path) / n
}

// ---------- validation: every check returns { valid, message } ----------

private fun valid() = obj("valid", true, "message", "")

private fun invalid(message: String) = obj("valid", false, "message", message)

fun checkRequired(v: Any?, field: Any?): MutableMap<String, Any?> = if (isEmpty(v)) invalid(str(field) + " is required") else valid()

private val EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$", Pattern.UNICODE_CHARACTER_CLASS)

fun checkEmail(v: Any?, field: Any?): MutableMap<String, Any?> =
    if (v is String && EMAIL.matcher(v).find()) valid() else invalid(str(field) + " must be a valid email")

private fun valueType(v: Any?): String = when (v) {
    null -> "null"
    is List<*> -> "array"
    is Number -> {
        val d = v.toDouble()
        if (d.isFinite() && Math.floor(d) == d) "integer" else "number"
    }
    is String -> "string"
    is Boolean -> "boolean"
    else -> "object"
}

fun checkType(v: Any?, type: Any?, field: Any?): MutableMap<String, Any?> {
    val vt = valueType(v)
    val t = str(type)
    return if (vt == t || (t == "number" && vt == "integer")) valid() else invalid(str(field) + " must be " + t)
}

/** The first problem of a value against a shape, or null. */
private fun checkValue(v: Any?, s: Any?, path: String): String? {
    if (s !is Map<*, *> || eq(get(s, "type"), "any")) return null
    val type = get(s, "type")
    if (v == null) return if (truthy(get(s, "nullable")) || eq(type, "null")) null else "$path is null"
    val t = valueType(v)
    if (eq(type, "number") && (t == "integer" || t == "number")) return null
    if (!eq(type, t)) return path + ": expected " + str(type) + ", got " + t
    val en = get(s, "enum")
    if (en is List<*> && en.isNotEmpty() && !includes(en, v)) return path + ": " + json(v) + " is not one of " + en.joinToString(", ") { jsString(it) }
    val props = get(s, "properties")
    if (props is Map<*, *> && t == "object" && v is Map<*, *>) {
        for ((k, f) in props) {
            if (!v.containsKey(k)) {
                if (truthy(get(f, "required"))) return "$path.$k is missing"
                continue
            }
            checkValue(v[k], f, "$path.$k")?.let { return it }
        }
    }
    if (v is List<*>) for ((i, x) in v.withIndex()) checkValue(x, get(s, "items"), "$path[$i]")?.let { return it }
    return null
}

fun checkShape(v: Any?, shape: Any?, field: Any?): MutableMap<String, Any?> {
    val p = checkValue(v, shape, str(field))
    return if (p != null) invalid(p) else valid()
}

fun checkRange(v: Any?, lo: Any?, hi: Any?, field: Any?): MutableMap<String, Any?> {
    if (v !is Number) return invalid(str(field) + " must be a number")
    val n = v.toDouble()
    if (lo != null && !eq(lo, "") && n < toNum(lo)) return invalid(str(field) + " must be ≥ " + jsString(lo))
    if (hi != null && !eq(hi, "") && n > toNum(hi)) return invalid(str(field) + " must be ≤ " + jsString(hi))
    return valid()
}

fun checkRegex(v: Any?, pattern: Any?, field: Any?): MutableMap<String, Any?> {
    val re = try {
        Pattern.compile(str(pattern))
    } catch (e: PatternSyntaxException) {
        return invalid("invalid pattern")
    }
    return if (re.matcher(str(v)).find()) valid() else invalid(str(field) + " has an invalid format")
}

fun checkPassword(v: Any?, policy: Any?, field: Any?): MutableMap<String, Any?> {
    val p = str(v)
    val min = toNum(get(policy, "minLength"))
    if (p.length < min) return invalid(str(field) + " must be at least " + numText(min) + " characters")
    if (truthy(get(policy, "requireDigit")) && p.none { it in '0'..'9' }) return invalid(str(field) + " must contain a digit")
    if (truthy(get(policy, "requireUpper")) && p.none { it in 'A'..'Z' }) return invalid(str(field) + " must contain an uppercase letter")
    return valid()
}

// ---------- conversion ----------

/** Objects become JSON. */
fun toStringValue(v: Any?): String = if (container(v)) json(v) else if (v == null) "" else jsString(v)

/** Not a number is 0. */
fun toNumber(v: Any?): Double {
    val n = jsNumber(v)
    return if (n.isNaN()) 0.0 else n
}

fun isNumeric(v: Any?): Boolean = !jsNumber(v).isNaN()

fun toBoolean(v: Any?): Boolean = truthy(v)

/** string, integer, number, boolean, object, array or null. */
fun typeOf(v: Any?): String = valueType(v)

// ---------- math ----------

/** 0-15 decimals, halves up. */
fun round(v: Any?, decimals: Any?): Double {
    val x = toNum(v)
    val d = trunc(toNum(decimals))
    val f = Math.pow(10.0, if (d.isFinite()) Math.min(15.0, Math.max(0.0, d)) else 0.0)
    val y = x * f + 0.5
    return if (y.isFinite()) Math.floor(y) / f else x
}

fun floor(v: Any?): Double = Math.floor(toNum(v))

fun ceil(v: Any?): Double = Math.ceil(toNum(v))

fun abs(v: Any?): Double = Math.abs(toNum(v))

fun min(a: Any?, b: Any?): Double = Math.min(toNum(a), toNum(b))

fun max(a: Any?, b: Any?): Double = Math.max(toNum(a), toNum(b))

/** Keeps the value between lo and hi. */
fun clamp(v: Any?, lo: Any?, hi: Any?): Double = Math.min(Math.max(toNum(v), toNum(lo)), toNum(hi))

/** JavaScript's ** (1 ** Infinity is NaN). */
fun power(a: Any?, b: Any?): Double {
    val x = toNum(a)
    val y = toNum(b)
    return if (y.isNaN() || (Math.abs(x) == 1.0 && y.isInfinite())) Double.NaN else Math.pow(x, y)
}

fun sqrt(v: Any?): Double = Math.sqrt(toNum(v))

// ---------- text and encoding ----------

/** A slice position: negative counts from the end, clamped to 0..n. */
private fun relIndex(v: Any?, n: Int): Int {
    val r = trunc(toNum(v))
    if (r.isNaN()) return 0
    return if (r < 0) Math.max(n + r, 0.0).toInt() else Math.min(r, n.toDouble()).toInt()
}

/** Like String.prototype.slice; a null end means the end of the text. */
fun substring(text: Any?, start: Any?, end: Any?): String {
    val t = str(text)
    val i = relIndex(start, t.length)
    val j = if (end == null) t.length else relIndex(end, t.length)
    return if (j <= i) "" else t.substring(i, j)
}

fun indexOf(text: Any?, search: Any?): Double = str(text).indexOf(str(search)).toDouble()

private fun pad(text: Any?, length: Any?, fill: Any?, atStart: Boolean): String {
    val t = str(text)
    val n = trunc(toNum(length))
    if (n > 100000) throw FddError("INVALID_LENGTH", "Length must be at most 100000")
    val f = if (fill == null) " " else str(fill)
    if (n.isNaN() || n <= t.length || f.isEmpty()) return t
    val need = n.toInt() - t.length
    val sb = StringBuilder()
    while (sb.length < need) sb.append(f)
    sb.setLength(need)
    return if (atStart) sb.toString() + t else t + sb
}

fun padStart(text: Any?, length: Any?, fill: Any?): String = pad(text, length, fill, true)

fun padEnd(text: Any?, length: Any?, fill: Any?): String = pad(text, length, fill, false)

/** UTF-8 text as Base64. */
fun base64Encode(text: Any?): String = Base64.getEncoder().encodeToString(str(text).toByteArray(Charsets.UTF_8))

private val BASE64_TEXT = Pattern.compile("^[A-Za-z0-9+/]*$")

/** Base64 as UTF-8 text; fails with INVALID_BASE64. */
fun base64Decode(text: Any?): String {
    var t = str(text).replace(Regex("[\\t\\n\\u000c\\r ]+"), "")
    if (t.length % 4 == 0) t = t.replace(Regex("={1,2}$"), "")
    if (t.length % 4 == 1 || !BASE64_TEXT.matcher(t).matches()) throw FddError("INVALID_BASE64", "Not valid Base64")
    return try {
        String(Base64.getDecoder().decode(t + "=".repeat((4 - t.length % 4) % 4)), Charsets.UTF_8)
    } catch (e: IllegalArgumentException) {
        throw FddError("INVALID_BASE64", "Not valid Base64")
    }
}

/** Fixed decimals (halves up) and a thousands separator; fails with INVALID_NUMBER. */
fun formatNumber(value: Any?, decimals: Any?, thousands: Any?, point: Any?): String {
    val d0 = trunc(toNum(decimals))
    val d = if (d0.isFinite()) Math.min(15.0, Math.max(0.0, d0)).toInt() else 0
    val r = round(value, d.toDouble())
    if (!r.isFinite() || Math.abs(r) >= 1e21) throw FddError("INVALID_NUMBER", "Not a number that can be formatted")
    val text = BigDecimal(Math.abs(r)).setScale(d, RoundingMode.HALF_EVEN).toPlainString()
    val dot = text.indexOf('.')
    var whole = if (dot < 0) text else text.substring(0, dot)
    val frac = if (dot < 0) "" else text.substring(dot + 1)
    val sign = if (r < 0 && (whole + frac).any { it in '1'..'9' }) "-" else ""
    val groups = ArrayList<String>()
    while (whole.length > 3) {
        groups.add(0, whole.substring(whole.length - 3))
        whole = whole.substring(0, whole.length - 3)
    }
    groups.add(0, whole)
    return sign + groups.joinToString(str(thousands)) + (if (frac.isNotEmpty()) str(point) + frac else "")
}

/** sha256, sha1 or md5 ("SHA-256" too); fails with INVALID_ALGORITHM. */
private fun digestAlgorithm(a: Any?): String {
    val k = jsTrim(str(a)).lowercase().replace("-", "")
    if (k != "sha256" && k != "sha1" && k != "md5") throw FddError("INVALID_ALGORITHM", "Unknown hash algorithm \"" + str(a) + "\" (use sha256, sha1 or md5)")
    return k
}

/** hex or base64; fails with INVALID_ENCODING. */
private fun encodeDigest(b: ByteArray, encoding: Any?): String = when (jsTrim(str(encoding)).lowercase()) {
    "hex" -> b.joinToString("") { String.format("%02x", it.toInt() and 0xff) }
    "base64" -> Base64.getEncoder().encodeToString(b)
    else -> throw FddError("INVALID_ENCODING", "Unknown encoding \"" + str(encoding) + "\" (use hex or base64)")
}

/** SHA-256, SHA-1 or MD5 of UTF-8 text, as hex or Base64. */
fun hash(text: Any?, algorithm: Any?, encoding: Any?): String {
    val name = when (digestAlgorithm(algorithm)) { "sha256" -> "SHA-256"; "sha1" -> "SHA-1"; else -> "MD5" }
    return encodeDigest(MessageDigest.getInstance(name).digest(str(text).toByteArray(Charsets.UTF_8)), encoding)
}

/** The HMAC of UTF-8 text with a UTF-8 key, as hex or Base64. */
fun hmac(text: Any?, key: Any?, algorithm: Any?, encoding: Any?): String {
    val name = when (digestAlgorithm(algorithm)) { "sha256" -> "HmacSHA256"; "sha1" -> "HmacSHA1"; else -> "HmacMD5" }
    val k = str(key).toByteArray(Charsets.UTF_8)
    val mac = Mac.getInstance(name)
    // an empty key is padded with zero bytes, like a key of one zero byte
    mac.init(SecretKeySpec(if (k.isEmpty()) byteArrayOf(0) else k, name))
    return encodeDigest(mac.doFinal(str(text).toByteArray(Charsets.UTF_8)), encoding)
}

/** encodeURIComponent. */
fun urlEncode(text: Any?): String {
    val sb = StringBuilder()
    for (b in str(text).toByteArray(Charsets.UTF_8)) {
        val c = (b.toInt() and 0xff).toChar()
        if (c in 'a'..'z' || c in 'A'..'Z' || c in '0'..'9' || c in "-_.!~*'()") sb.append(c) else sb.append('%').append(String.format("%02X", b.toInt() and 0xff))
    }
    return sb.toString()
}

private fun asciiHex(c: Char) = c in '0'..'9' || c in 'a'..'f' || c in 'A'..'F'

private fun strictUtf8(buf: ByteArray): String =
    Charsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(buf)).toString()

/** decodeURIComponent; fails with INVALID_URL_ENCODING. */
fun urlDecode(text: Any?): String {
    val s = str(text)
    val sb = StringBuilder()
    val buf = java.io.ByteArrayOutputStream()
    try {
        var i = 0
        while (i < s.length) {
            if (s[i] == '%') {
                if (i + 2 >= s.length || !asciiHex(s[i + 1]) || !asciiHex(s[i + 2])) throw FddError("INVALID_URL_ENCODING", "Not valid URL encoding")
                buf.write(Character.digit(s[i + 1], 16) * 16 + Character.digit(s[i + 2], 16))
                i += 3
                continue
            }
            if (buf.size() > 0) {
                sb.append(strictUtf8(buf.toByteArray()))
                buf.reset()
            }
            sb.append(s[i])
            i++
        }
        if (buf.size() > 0) sb.append(strictUtf8(buf.toByteArray()))
    } catch (e: CharacterCodingException) {
        throw FddError("INVALID_URL_ENCODING", "Not valid URL encoding")
    }
    return sb.toString()
}

// ---------- records and lists ----------

private fun isIndexKey(k: String): Boolean {
    if (k != "0" && (k.isEmpty() || k[0] == '0' || !k.all { it in '0'..'9' })) return false
    return k.toDouble() < 4294967295.0
}

/** Field names in JavaScript's order: integer-like keys ascending, then the rest as inserted. */
private fun keyList(o: Any?): List<String> {
    if (o !is Map<*, *>) return emptyList()
    val keys = o.keys.map { it as String }
    return keys.filter { isIndexKey(it) }.sortedBy { it.toDouble() } + keys.filter { !isIndexKey(it) }
}

fun keys(o: Any?): MutableList<Any?> = keyList(o).toMutableList()

fun values(o: Any?): MutableList<Any?> = keyList(o).mapTo(ArrayList()) { (o as Map<*, *>)[it] }

fun entries(o: Any?): MutableList<Any?> = keyList(o).mapTo(ArrayList()) { obj("key", it, "value", (o as Map<*, *>)[it]) }

/** Like Array.prototype.slice; a null end means the end of the list. */
fun slice(a: Any?, start: Any?, end: Any?): MutableList<Any?> {
    val l = asArray(a)
    val i = relIndex(start, l.size)
    val j = if (end == null) l.size else relIndex(end, l.size)
    return if (j <= i) ArrayList() else ArrayList(l.subList(i, j))
}

fun reverse(a: Any?): MutableList<Any?> = asArray(a).reversed().toMutableList()

/** Removes deep-equal duplicates, the first kept. */
fun unique(a: Any?): MutableList<Any?> {
    val out = ArrayList<Any?>()
    for (x in asArray(a)) if (!includes(out, x)) out.add(x)
    return out
}

/** The deep-equal position, or -1. */
fun itemIndex(a: Any?, item: Any?): Double = asArray(a).indexOfFirst { deepEqual(it, item) }.toDouble()

/** Flattens one level. */
fun flatten(a: Any?): MutableList<Any?> {
    val out = ArrayList<Any?>()
    for (x in asArray(a)) if (x is List<*>) out.addAll(x) else out.add(x)
    return out
}

// ---------- dates: ISO 8601 text in UTC; numbers are epoch milliseconds ----------

private const val MIN_MS = -62167219200000L
private const val MAX_MS = 253402300799999L
private const val DAY_MS = 86400000L
private val DATE_TEXT = Pattern.compile("^([0-9]{4})-([0-9]{2})-([0-9]{2})(?:[Tt ]([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:\\.([0-9]+))?)?)?(?:([Zz])|([+-])([0-9]{2}):?([0-9]{2}))?$")
private val TIME_UNITS = listOf("millisecond", "milliseconds", "ms", "second", "seconds", "minute", "minutes", "hour", "hours", "day", "days", "week", "weeks", "month", "months", "year", "years")
private val TIME_UNIT_MS = longArrayOf(1, 1, 1, 1000, 1000, 60000, 60000, 3600000, 3600000, DAY_MS, DAY_MS, 7 * DAY_MS, 7 * DAY_MS, -1, -1, -12, -12)
private val MONTHS = listOf("January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December")
private val DAYS = listOf("Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday")
private val DATE_TOKENS = listOf("yyyy", "yy", "MMMM", "MMM", "MM", "M", "dd", "d", "EEEE", "EEE", "HH", "H", "hh", "h", "mm", "m", "ss", "s", "SSS", "a")

/** Days since 1970-01-01 (proleptic Gregorian). */
private fun daysFromCivil(y0: Long, m: Long, d: Long): Long {
    val y = if (m <= 2) y0 - 1 else y0
    val era = Math.floorDiv(y, 400L)
    val yoe = y - era * 400
    val doy = (153 * (if (m > 2) m - 3 else m + 9) + 2) / 5 + d - 1
    return era * 146097 + yoe * 365 + yoe / 4 - yoe / 100 + doy - 719468
}

private fun civilFromDays(z0: Long): LongArray {
    val z = z0 + 719468
    val era = Math.floorDiv(z, 146097L)
    val doe = z - era * 146097
    val yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365
    val doy = doe - (365 * yoe + yoe / 4 - yoe / 100)
    val mp = (5 * doy + 2) / 153
    val m = if (mp < 10) mp + 3 else mp - 9
    return longArrayOf(yoe + era * 400 + (if (m <= 2) 1 else 0), m, doy - (153 * mp + 2) / 5 + 1)
}

private fun daysIn(y: Long, m: Long): Long = when (m) {
    2L -> if (y % 4 == 0L && (y % 100 != 0L || y % 400 == 0L)) 29 else 28
    4L, 6L, 9L, 11L -> 30
    else -> 31
}

/** The epoch milliseconds of a date (years 0-9999), or null. */
private fun dateMs(v: Any?): Long? {
    val ms: Long = when (v) {
        is Number -> {
            val x = v.toDouble()
            if (!x.isFinite() || trunc(x) < MIN_MS || trunc(x) > MAX_MS) return null
            trunc(x).toLong()
        }
        is String -> {
            val m = DATE_TEXT.matcher(jsTrim(v))
            if (!m.matches()) return null
            val g = { k: Int -> m.group(k)?.toLong() ?: 0L }
            val y = g(1)
            val mo = g(2)
            val d = g(3)
            val h = g(4)
            val mi = g(5)
            val sec = g(6)
            if (mo < 1 || mo > 12 || d < 1 || d > daysIn(y, mo) || h > 23 || mi > 59 || sec > 59) return null
            val tz = m.group(9) != null
            if (tz && (g(10) > 23 || g(11) > 59)) return null
            var off = if (tz) g(10) * 60 + g(11) else 0L
            if (m.group(9) == "-") off = -off
            val frac = ((m.group(7) ?: "") + "000").substring(0, 3).toLong()
            (daysFromCivil(y, mo, d) * 86400 + h * 3600 + mi * 60 + sec) * 1000 + frac - off * 60000
        }
        else -> return null
    }
    return if (ms in MIN_MS..MAX_MS) ms else null
}

private fun needDate(v: Any?): Long = dateMs(v) ?: throw FddError("INVALID_DATE", "Not a valid date")

/** [year, month, day, hour, minute, second, millisecond, weekday (0 = Sunday), time of day] */
private fun dateFields(ms: Long): LongArray {
    val days = Math.floorDiv(ms, DAY_MS)
    val t = ms - days * DAY_MS
    val c = civilFromDays(days)
    return longArrayOf(c[0], c[1], c[2], t / 3600000, t / 60000 % 60, t / 1000 % 60, t % 1000, Math.floorMod(days + 4, 7L), t)
}

private fun isoDate(ms: Double): String {
    if (!(ms >= MIN_MS && ms <= MAX_MS)) throw FddError("INVALID_DATE", "The date is out of range")
    val p = dateFields(ms.toLong())
    return String.format("%04d-%02d-%02dT%02d:%02d:%02d.%03dZ", p[0], p[1], p[2], p[3], p[4], p[5], p[6])
}

/** The milliseconds of a unit; months are -1 and years -12. */
private fun timeUnit(u: Any?): Long {
    val i = TIME_UNITS.indexOf(jsTrim(str(u)).lowercase())
    if (i < 0) throw FddError("INVALID_UNIT", "Unknown time unit \"" + str(u) + "\"")
    return TIME_UNIT_MS[i]
}

/** A date as UTC date-time text and epoch milliseconds. */
fun parseDate(v: Any?): MutableMap<String, Any?> {
    val ms = dateMs(v) ?: return obj("date", null, "timestamp", null, "valid", false)
    return obj("date", isoDate(ms.toDouble()), "timestamp", ms.toDouble(), "valid", true)
}

private fun zpad(n: Long, w: Int): String = n.toString().padStart(w, '0')

/** yyyy yy MMMM MMM MM M dd d EEEE EEE HH H hh h mm m ss s SSS a; text in single quotes is kept as is, and two single quotes are one. */
fun formatDate(date: Any?, pattern: Any?): String {
    val p = dateFields(needDate(date))
    val f = str(pattern)
    val h12 = if (p[3] % 12 == 0L) 12L else p[3] % 12
    val month = MONTHS[(p[1] - 1).toInt()]
    val day = DAYS[p[7].toInt()]
    val values = listOf(zpad(p[0], 4), zpad(p[0] % 100, 2), month, month.substring(0, 3), zpad(p[1], 2), p[1].toString(), zpad(p[2], 2), p[2].toString(), day,
        day.substring(0, 3), zpad(p[3], 2), p[3].toString(), zpad(h12, 2), h12.toString(), zpad(p[4], 2), p[4].toString(), zpad(p[5], 2), p[5].toString(),
        zpad(p[6], 3), if (p[3] < 12) "AM" else "PM")
    val out = StringBuilder()
    var i = 0
    while (i < f.length) {
        if (f[i] == '\'') {
            if (i + 1 < f.length && f[i + 1] == '\'') {
                out.append('\'')
                i += 2
                continue
            }
            i++
            while (i < f.length) {
                if (f[i] != '\'') out.append(f[i])
                else if (i + 1 < f.length && f[i + 1] == '\'') {
                    out.append('\'')
                    i++
                } else break
                i++
            }
            i++
            continue
        }
        val k = DATE_TOKENS.indexOfFirst { f.startsWith(it, i) }
        if (k >= 0) {
            out.append(values[k])
            i += DATE_TOKENS[k].length
        } else {
            out.append(f[i])
            i++
        }
    }
    return out.toString()
}

/** Months and years keep the day, clamped to the end of the month. */
fun addTime(date: Any?, amount: Any?, unit: Any?): String {
    val ms = needDate(date)
    val u = timeUnit(unit)
    val n = toNum(amount)
    if (!n.isFinite()) throw FddError("INVALID_DATE", "The date is out of range")
    if (u > 0) return isoDate(ms + Math.floor(n * u + 0.5))
    if (Math.abs(trunc(n)) > 1e6) throw FddError("INVALID_DATE", "The date is out of range")
    val p = dateFields(ms)
    val total = p[0] * 12 + p[1] - 1 + trunc(n).toLong() * -u
    val y = Math.floorDiv(total, 12L)
    val m = total - y * 12 + 1
    return isoDate((daysFromCivil(y, m, Math.min(p[2], daysIn(y, m))) * DAY_MS + p[8]).toDouble())
}

/** Whole units from From to To, toward zero. */
fun timeBetween(from: Any?, to: Any?, unit: Any?): Double {
    val a = needDate(from)
    val b = needDate(to)
    val u = timeUnit(unit)
    if (u > 0) return trunc((b - a).toDouble() / u) + 0.0
    val p = dateFields(a)
    val q = dateFields(b)
    var months = (q[0] - p[0]) * 12 + q[1] - p[1]
    if (months > 0 && (q[2] < p[2] || (q[2] == p[2] && q[8] < p[8]))) months--
    else if (months < 0 && (q[2] > p[2] || (q[2] == p[2] && q[8] > p[8]))) months++
    return trunc(months.toDouble() / -u) + 0.0
}

/** year ... millisecond in UTC, weekday 1 = Monday ... 7 = Sunday. */
fun dateParts(date: Any?): MutableMap<String, Any?> {
    val p = dateFields(needDate(date))
    return obj("year", p[0].toDouble(), "month", p[1].toDouble(), "day", p[2].toDouble(), "hour", p[3].toDouble(), "minute", p[4].toDouble(),
        "second", p[5].toDouble(), "millisecond", p[6].toDouble(), "weekday", (if (p[7] == 0L) 7L else p[7]).toDouble())
}

/** A UTC date-time from its parts; fails with INVALID_DATE. */
fun makeDate(year: Any?, month: Any?, day: Any?, hour: Any?, minute: Any?, second: Any?): String {
    val v = listOf(year, month, day, hour, minute, second).map { toNum(it) }
    if (v.any { !it.isFinite() || Math.floor(it) != it }) throw FddError("INVALID_DATE", "Not a valid date")
    val (y, m, d, h, mi, s) = v.map { it.toLong() }
    if (y < 0 || y > 9999 || m < 1 || m > 12 || d < 1 || d > daysIn(y, m) || h < 0 || h > 23 || mi < 0 || mi > 59 || s < 0 || s > 59) throw FddError("INVALID_DATE", "Not a valid date")
    return isoDate(((daysFromCivil(y, m, d) * 86400 + h * 3600 + mi * 60 + s) * 1000).toDouble())
}

private operator fun <T> List<T>.component6(): T = this[5]

private val PERIODS = listOf("hour", "hours", "day", "days", "week", "weeks", "month", "months", "year", "years")

/** The first (or last) millisecond of the hour, day, week from Monday, month or year. */
private fun periodEdge(date: Any?, unit: Any?, end: Boolean): String {
    val ms = needDate(date)
    val p = dateFields(ms)
    val day = Math.floorDiv(ms, DAY_MS) * DAY_MS
    val u = PERIODS.indexOf(jsTrim(str(unit)).lowercase())
    if (u < 0) throw FddError("INVALID_UNIT", "Unknown period \"" + str(unit) + "\" (use hour, day, week, month or year)")
    val (from, length) = when (u / 2) {
        0 -> Pair(ms - p[8] % 3600000, 3600000L)
        1 -> Pair(day, DAY_MS)
        2 -> Pair(day - (p[7] + 6) % 7 * DAY_MS, 7 * DAY_MS)
        3 -> Pair(daysFromCivil(p[0], p[1], 1) * DAY_MS, daysIn(p[0], p[1]) * DAY_MS)
        else -> Pair(daysFromCivil(p[0], 1, 1) * DAY_MS, (daysFromCivil(p[0] + 1, 1, 1) - daysFromCivil(p[0], 1, 1)) * DAY_MS)
    }
    return isoDate((if (end) from + length - 1 else from).toDouble())
}

/** The first moment of the period the date is in (UTC). */
fun startOf(date: Any?, unit: Any?): String = periodEdge(date, unit, false)

/** The last moment (...:59.999) of the period the date is in (UTC). */
fun endOf(date: Any?, unit: Any?): String = periodEdge(date, unit, true)

// ---------- runtime ----------

/** The current date-time (ISO, like JavaScript's toISOString). */
fun now(): String = isoDate(System.currentTimeMillis().toDouble())

fun uuid(): String = UUID.randomUUID().toString()

/** An integer between min and max. */
fun random(min: Any?, max: Any?): Double {
    val a = toNum(min)
    val b = toNum(max)
    return Math.floor(a + ThreadLocalRandom.current().nextDouble() * (b - a + 1))
}

fun log(message: Any?): Any? {
    println(if (message is String) message else json(message))
    return null
}

fun sleep(ms: Any?): Any? {
    Thread.sleep(Math.max(0.0, toNum(ms)).toLong())
    return null
}

/** Runs the branches on threads and waits for all; the first branch's error is thrown again. */
fun parallel(vararg branches: () -> Unit) {
    val failed = arrayOfNulls<Throwable>(branches.size)
    val threads = branches.mapIndexed { i, b -> Thread { try { b() } catch (e: Throwable) { failed[i] = e } } }
    threads.forEach { it.start() }
    threads.forEach { it.join() }
    failed.firstOrNull { it != null }?.let { throw it }
}

